import json,struct,gzip,base64,zipfile,math,collections,hashlib
from pathlib import Path
P=Path(__file__).resolve().parent;ROOT=P.parent
ASSET=next(d for parent in [P.parent,*P.parents] for d in [parent/'开源模型',parent/'original-project/开源模型'] if d.exists())
models=[];measure=[]
def add(name,v,kind):
 lo=[min(t[i] for t in v) for i in range(3)];hi=[max(t[i] for t in v) for i in range(3)]
 models.append({'name':name,'kind':kind,'lo':lo,'hi':hi,'data':base64.b64encode(gzip.compress(struct.pack('<%sf'% (len(v)*3),*(a for t in v for a in t)))).decode(),'n':len(v)})
 return lo,hi
for p in sorted(ASSET.glob('*.STL')):
 b=p.read_bytes();n=struct.unpack_from('<I',b,80)[0];v=[struct.unpack_from('<3f',b,84+j*50+12+k*12) for j in range(n) for k in range(3)]
 lo,hi=add(p.name,v,'grip' if p.name.startswith('枪体壳') else 'base' if p.name.startswith('底座') else 'part')
 edges=collections.Counter(tuple(sorted((v[j+a],v[j+c]))) for j in range(0,len(v),3) for a,c in [(0,1),(1,2),(2,0)])
 measure.append({'file':p.name,'unit':'mm (project assumption, STL has no unit)','source':'original GitHub blob matched','git_blob':hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest(),'bounds':[lo,hi],'size':[hi[i]-lo[i] for i in range(3)],'triangles':n,'edges_used_not_twice':sum(k!=2 for k in edges.values()),'self_intersection':'not_checked','global_wall_thickness':'not_checked'})
z=zipfile.ZipFile((P/'pcb-assembly-obj.zip') if (P/'pcb-assembly-obj.zip').exists() else ROOT/'PCB审核_2026-11-05/R0-assembly-3d.zip');s=z.read('R0-assembly-review.obj').decode();verts=[];vv=[]
for l in s.splitlines():
 if l.startswith('v '):verts.append(tuple(map(float,l.split()[1:4])))
 elif l.startswith('f '):
  ids=[int(a.split('/')[0])-1 for a in l.split()[1:]]
  for j in range(1,len(ids)-1):vv.extend([verts[ids[0]],verts[ids[j]],verts[ids[j+1]]])
add('实际 PCB 与器件（EDA OBJ）',vv,'pcb')
(P/'模型尺寸与拓扑记录.json').write_text(json.dumps(measure,ensure_ascii=False,indent=2))
html='''<!doctype html><html lang="zh"><meta charset="utf-8"><title>R0 · 装配审查</title><style>body{margin:0;background:#101923;color:#e4edf4;font:15px system-ui}header{padding:22px 28px;border-bottom:1px solid #334450}h1{font-size:24px;margin:0 0 8px}main{display:flex;height:78vh}aside{width:280px;padding:20px;overflow:auto}canvas{width:calc(100% - 320px);height:100%;touch-action:none}button,select{padding:10px;margin:4px;background:#20384b;color:white;border:1px solid #567;border-radius:8px}small{display:block;line-height:1.7;color:#b8cad8}label{display:block;margin:8px 0}.warn{color:#ffcb85}footer{padding:16px 28px}</style><header><h1>手控云台 R0 · 三维审查</h1><small>真实 STL / EDA 导出几何 · 拖动旋转，滚轮缩放 · 候选位置仅用于评审</small></header><main><aside><select id="mode"><option value="pcb">PCB 与器件</option><option value="grip">原始手柄分件</option><option value="fit">手柄＋PCB 候选位置</option><option value="base">原始底座分件</option><option value="part">其余原始零件</option></select><label>分解间距 <input id="explode" type="range" min="0" max="40" value="0"></label><button id="reset">恢复视角</button><div id="parts"></div><p class="warn">候选安装位置未通过完整干涉检查。外壳保持原始版本，未宣称实装适配。</p><small id="info"></small></aside><canvas id="c"></canvas></main><footer>保留原外观 · PCB 56×80 mm · 外壳单位按项目 mm 解释 · 非打板或打印放行</footer><script>const M=MODELS;
const canvas=document.getElementById('c'),gl=canvas.getContext('webgl2');if(!gl)throw Error('需要支持 WebGL2 的浏览器');
const vs=`#version 300 es\nin vec3 p;uniform vec3 center;uniform float scale;uniform vec2 angle;uniform float aspect;uniform vec3 offset;uniform int pose;out vec3 xyz;void main(){vec3 q=p;if(pose==1)q=vec3(15.+p.z,1.+p.x,200.+p.y);q+=offset;q-=center;float a=angle.x,b=angle.y;vec3 r=vec3(cos(a)*q.x-sin(a)*q.y,sin(a)*q.x+cos(a)*q.y,q.z);r=vec3(r.x,cos(b)*r.y-sin(b)*r.z,sin(b)*r.y+cos(b)*r.z);xyz=r;gl_Position=vec4(r.x*scale/aspect,r.y*scale,r.z*scale*.15,1.);}`;
const fs=`#version 300 es\nprecision highp float;in vec3 xyz;uniform vec3 color;out vec4 outc;void main(){vec3 n=normalize(cross(dFdx(xyz),dFdy(xyz)));float l=.35+.65*abs(dot(n,normalize(vec3(.4,.5,1.))));outc=vec4(color*l,1.);}`;
function sh(type,s){let h=gl.createShader(type);gl.shaderSource(h,s);gl.compileShader(h);if(!gl.getShaderParameter(h,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(h));return h}let prog=gl.createProgram();gl.attachShader(prog,sh(gl.VERTEX_SHADER,vs));gl.attachShader(prog,sh(gl.FRAGMENT_SHADER,fs));gl.linkProgram(prog);gl.useProgram(prog);const U={};for(let n of ['center','scale','angle','aspect','offset','pose','color'])U[n]=gl.getUniformLocation(prog,n);let a=.5,b=-1.1,zoom=1,loaded=false;
async function init(){for(const m of M){let bytes=Uint8Array.from(atob(m.data),c=>c.charCodeAt(0));let raw=await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();m.buf=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,m.buf);gl.bufferData(gl.ARRAY_BUFFER,raw,gl.STATIC_DRAW)}loaded=true;select()}let active=[];
function select(){const mode=document.getElementById('mode').value;active=M.filter(m=>mode==='fit'?['grip','pcb'].includes(m.kind):m.kind===mode);document.getElementById('parts').innerHTML=active.map((m,i)=>`<label><input type="checkbox" checked data-i="${i}">${m.name}</label>`).join('');active.forEach(m=>m.on=true);for(let el of document.querySelectorAll('[data-i]'))el.onchange=()=>{active[el.dataset.i].on=el.checked;draw()};zoom=1;document.getElementById('info').textContent=mode==='fit'?'候选变换 X=15+PCB_Z，Y=1+PCB_X，Z=200+PCB_Y，单位 mm。红色为实际 PCB 几何。':active.map(m=>m.name+': '+m.lo.map((v,i)=>(m.hi[i]-v).toFixed(1)).join(' × ')+' mm').join('；');draw()}
function draw(){if(!loaded)return;canvas.width=canvas.clientWidth*devicePixelRatio;canvas.height=canvas.clientHeight*devicePixelRatio;gl.viewport(0,0,canvas.width,canvas.height);gl.clearColor(.055,.09,.13,1);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.enable(gl.DEPTH_TEST);let mode=document.getElementById('mode').value;let boxes=active.filter(m=>m.on).map(m=>mode==='fit'&&m.kind==='pcb'?{lo:[15+m.lo[2],1+m.lo[0],200+m.lo[1]],hi:[15+m.hi[2],1+m.hi[0],200+m.hi[1]]}:m);if(!boxes.length)return;let lo=[0,1,2].map(i=>Math.min(...boxes.map(m=>m.lo[i]))),hi=[0,1,2].map(i=>Math.max(...boxes.map(m=>m.hi[i]))),center=lo.map((v,i)=>(v+hi[i])/2),radius=Math.hypot(...hi.map((v,i)=>v-lo[i]))/2;gl.uniform3fv(U.center,center);gl.uniform1f(U.scale,zoom*.85/Math.max(radius,1));gl.uniform2f(U.angle,a,b);gl.uniform1f(U.aspect,canvas.width/canvas.height);let ex=+document.getElementById('explode').value;active.forEach((m,i)=>{if(!m.on)return;gl.uniform3fv(U.offset,[ex*(i-(active.length-1)/2),0,0]);gl.uniform1i(U.pose,mode==='fit'&&m.kind==='pcb'?1:0);gl.uniform3fv(U.color,m.kind==='pcb'?[.9,.35,.2]:[.25+i*.08,.62,.72]);gl.bindBuffer(gl.ARRAY_BUFFER,m.buf);let pos=gl.getAttribLocation(prog,'p');gl.enableVertexAttribArray(pos);gl.vertexAttribPointer(pos,3,gl.FLOAT,false,0,0);gl.drawArrays(gl.TRIANGLES,0,m.n)})}
let drag=false,last;canvas.onpointerdown=e=>{drag=true;last=[e.clientX,e.clientY];canvas.setPointerCapture(e.pointerId)};canvas.onpointerup=()=>drag=false;canvas.onpointermove=e=>{if(drag){a+=(e.clientX-last[0])*.008;b+=(e.clientY-last[1])*.008;last=[e.clientX,e.clientY];draw()}};canvas.onwheel=e=>{e.preventDefault();zoom*=Math.exp(-e.deltaY*.001);draw()};document.getElementById('mode').onchange=select;document.getElementById('explode').oninput=draw;document.getElementById('reset').onclick=()=>{a=.5;b=-1.1;zoom=1;draw()};window.onresize=draw;init();</script></html>'''
(P/'装配展示.html').write_text(html.replace('MODELS',json.dumps(models,ensure_ascii=False,separators=(',',':'))))
print('models',len(models),'html bytes',(P/'装配展示.html').stat().st_size)
